import com.comsol.model.util.*
model = mphload('busbar.mph');
disp(mphversion)

model = mphload('busbar.mph');
for V = [10 20 30]
    model.param.set('Vtot', sprintf('%d[mV]', V));
    model.study('std1').run();
    fprintf('V = %d mV -> Tmax = %.2f K\n', V, mphmax(model, 'T', 'volume'));
end
mphsave(model, 'busbar_sweep.mph');

pd = mpheval(model, {'T','ht.tfluxMag'}, 'edim', 'domain', 'selection', 1);
coords = pd.p;     % 3 x N point coordinates
T      = pd.d1;    % 1 x N temperature values
flux   = pd.d2;
fprintf('Tmax = %.2f %s\n', max(T), pd.unit{1});

coord = [0 0 0; 0.05 0 0.01; 0.10 0 0.02]';   % columns are points
[T, unit] = mphinterp(model, 'T', 'coord', coord, ...
                      'dataset', 'dset1', 'edim', 'domain');
fprintf('T = %.2f %s at the last probe point\n', T(end), unit);

Q = mphint2(model, 'ec.Qh', 'volume', 'selection', 1);
[I, unit] = mphint2(model, 'ec.normJ', 'surface', 'selection', 43);
fprintf('Heat = %.4f W, current = %.2f %s\n', Q, I, unit);

Vtot = mphglobal(model, 'Vtot');                 % a parameter
I    = mphglobal(model, 'ec.I0_1', 'dataset', 'dset2');
plot(mphglobal(model, 'freq'), 20*log10(abs(I)));
xlabel('Frequency (Hz)'); ylabel('|I| (dB)');

